class Solution {
public:
    int strangePrinter(string s) {
        int n = s.size();
        if (n == 0) return 0;
        vector<vector<int>> dp(n, vector<int>(n, 0));
        for (int i = 0; i < n; i++) dp[i][i] = 1;
        for (int len = 2; len <= n; len++) {
            for (int i = 0; i + len - 1 < n; i++) {
                int j = i + len - 1;
                dp[i][j] = dp[i][j - 1] + 1;
                for (int k = i; k < j; k++) {
                    if (s[k] == s[j]) {
                        int interior = (k + 1 <= j - 1) ? dp[k + 1][j - 1] : 0;
                        int cand = dp[i][k] + interior;
                        if (cand < dp[i][j]) dp[i][j] = cand;
                    }
                }
            }
        }
        return dp[0][n - 1];
    }
};
